import ctypes
from typing import Optional
from qiling.core import Qiling

from qiling.hw.peripheral import QlPeripheral
from qiling.hw.timer.timer import QlTimerPeripheral
from qiling.hw.const.stm32f4xx_tim import TIM_DIER, TIM_SR, TIM_CR1


class STM32F4xxTim(QlTimerPeripheral):
    class Type(ctypes.Structure):
        """ the structure available in :
                stm32f401xc
                stm32f401xe
                stm32f405xx
                stm32f407xx
                stm32f410cx
                stm32f410rx
                stm32f410tx
                stm32f411xe
                stm32f412cx
                stm32f412rx
                stm32f412vx
                stm32f412zx
                stm32f413xx
                stm32f415xx
                stm32f417xx
                stm32f423xx
                stm32f427xx
                stm32f429xx
                stm32f437xx
                stm32f439xx
                stm32f446xx
                stm32f469xx
                stm32f479xx
        """

        _fields_ = [
            ("CR1"  , ctypes.c_uint32), #TIM control register 1,              Address offset: 0x00
            ("CR2"  , ctypes.c_uint32), #TIM control register 2,              Address offset: 0x04
            ("SMCR" , ctypes.c_uint32), #TIM slave mode control register,     Address offset: 0x08
            ("DIER" , ctypes.c_uint32), #TIM DMA/interrupt enable register,   Address offset: 0x0C
            ("SR"   , ctypes.c_uint32), #TIM status register,                 Address offset: 0x10
            ("EGR"  , ctypes.c_uint32), #TIM event generation register,       Address offset: 0x14
            ("CCMR1", ctypes.c_uint32), #TIM capture/compare mode register 1, Address offset: 0x18
            ("CCMR2", ctypes.c_uint32), #TIM capture/compare mode register 2, Address offset: 0x1C
            ("CCER" , ctypes.c_uint32), #TIM capture/compare enable register, Address offset: 0x20
            ("CNT"  , ctypes.c_uint32), #TIM counter register,                Address offset: 0x24
            ("PSC"  , ctypes.c_uint32), #TIM prescaler,                       Address offset: 0x28
            ("ARR"  , ctypes.c_uint32), #TIM auto-reload register,            Address offset: 0x2C
            ("RCR"  , ctypes.c_uint32), #TIM repetition counter register,     Address offset: 0x30
            ("CCR1" , ctypes.c_uint32), #TIM capture/compare register 1,      Address offset: 0x34
            ("CCR2" , ctypes.c_uint32), #TIM capture/compare register 2,      Address offset: 0x38
            ("CCR3" , ctypes.c_uint32), #TIM capture/compare register 3,      Address offset: 0x3C
            ("CCR4" , ctypes.c_uint32), #TIM capture/compare register 4,      Address offset: 0x40
            ("BDTR" , ctypes.c_uint32), #TIM break and dead-time register,    Address offset: 0x44
            ("DCR"  , ctypes.c_uint32), #TIM DMA control register,            Address offset: 0x48
            ("DMAR" , ctypes.c_uint32), #TIM DMA address for full transfer,   Address offset: 0x4C
            ("OR"   , ctypes.c_uint32), #TIM option register,                 Address offset: 0x50
        ]

    def __init__(self, ql: Qiling, label: str, 
            intn: Optional[int] = None, 
            brk_intn: Optional[int] = None, 
            cc_intn: Optional[int] = None,
            trg_com_intn: Optional[int] = None,
            up_intn: Optional[int] = None):

        super().__init__(ql, label)

        self.intn = intn
        self.brk_intn = brk_intn if brk_intn else intn
        self.cc_intn = cc_intn if cc_intn else intn
        self.trg_com_intn = trg_com_intn if trg_com_intn else intn
        self.up_intn = up_intn if up_intn else intn


        self.prescale_count = 0
        self.instance = self.struct()

    @QlPeripheral.monitor()
    def read(self, offset: int, size: int) -> int:
        buf = ctypes.create_string_buffer(size)
        ctypes.memmove(buf, ctypes.addressof(self.instance) + offset, size)
        return int.from_bytes(buf.raw, byteorder='little')

    @QlPeripheral.monitor()
    def write(self, offset: int, size: int, value: int):
        data = (value).to_bytes(size, 'little')
        ctypes.memmove(ctypes.addressof(self.instance) + offset, data, size)

    def send_update_interrupt(self):
        if self.up_intn is None:
            return

        if not self.instance.DIER & TIM_DIER.UIE:
            return

        self.instance.SR |= TIM_SR.UIF
        self.ql.hw.nvic.set_pending(self.up_intn)

    def set_ratio(self, ratio):
        self.instance.CNT = 0
        self.prescale_count = 0

        self._ratio = ratio

    @property
    def ratio(self):
        return max(round(self._ratio / (self.instance.PSC + 1)), 1)

    @ratio.setter
    def ratio(self, value):
        self.set_ratio(value)

    @property
    def prescale(self):
        return max(round((self.instance.PSC + 1) / self._ratio) - 1, 0)

    def step(self):
        if self.instance.CR1 & TIM_CR1.CEN:
            if self.instance.CNT >= self.instance.ARR:
                self.instance.CNT = 0
                self.prescale_count = 0
                self.send_update_interrupt()

            elif self.prescale_count == self.prescale:
                self.prescale_count = 0
                self.instance.CNT += self.ratio

            else:
                self.prescale_count += 1
#!/usr/bin/env python3
#
# Cross Platform and Multi Architecture Advanced Binary Emulation Framework
#

from functools import cached_property
from typing import Any, Dict, List, Optional, Tuple

from qiling import Qiling
from qiling.hw.peripheral import QlPeripheral
from qiling.utils import ql_get_module_function
from qiling.exception import QlErrorModuleFunctionNotFound


# should adhere to the QlMmioHandler interface, but not extend it directly to
# avoid potential pickling issues
class QlPripheralHandler:
    def __init__(self, hwman: "QlHwManager", base: int, size: int, label: str) -> None:
        self._hwman = hwman
        self._base = base
        self._size = size
        self._label = label

    def __getstate__(self):
        state = self.__dict__.copy()
        del state['_hwman']  # remove non-pickleable reference

        return state

    @cached_property
    def _mmio(self) -> bytearray:
        """Get memory buffer used to back non-mapped hardware mmio regions.
        """

        return bytearray(self._size)

    def read(self, ql: Qiling, offset: int, size: int) -> int:
        address = self._base + offset
        hardware = self._hwman.find(address)

        if hardware:
            return hardware.read(address - hardware.base, size)

        else:
            ql.log.debug('[%s] read non-mapped hardware [%#010x]', self._label, address)
            return int.from_bytes(self._mmio[offset:offset + size], byteorder='little')

    def write(self, ql: Qiling, offset: int, size: int, value: int) -> None:
        address = self._base + offset
        hardware = self._hwman.find(address)

        if hardware:
            hardware.write(address - hardware.base, size, value)

        else:
            ql.log.debug('[%s] write non-mapped hardware [%#010x] = %#010x', self._label, address, value)
            self._mmio[offset:offset + size] = value.to_bytes(size, 'little')


class QlHwManager:
    def __init__(self, ql: Qiling):
        self.ql = ql

        self.entity: Dict[str, QlPeripheral] = {}
        self.region: Dict[str, List[Tuple[int, int]]] = {}

    def create(self, label: str, struct: Optional[str] = None, base: Optional[int] = None, kwargs: Optional[Dict[str, Any]] = None) -> QlPeripheral:
        """ Create the peripheral accroding the label and envs.

            struct: Structure of the peripheral. Use defualt ql structure if not provide.
            base: Base address. Use defualt address if not provide.
        """

        if struct is None:
            struct, base, kwargs = self.load_env(label.upper())

        if kwargs is None:
            kwargs = {}

        try:
            entity = ql_get_module_function('qiling.hw', struct)(self.ql, label, **kwargs)

        except QlErrorModuleFunctionNotFound:
            self.ql.log.warning(f'could not create {struct}({label}): implementation not found')

        else:
            assert isinstance(entity, QlPeripheral)
            assert isinstance(base, int)

            self.entity[label] = entity
            self.region[label] = [(lbound + base, rbound + base) for (lbound, rbound) in entity.region]

            return entity

        # FIXME: what should we do if struct is not implemented? is it OK to return None , or we fail?

    def delete(self, label: str) -> None:
        """ Remove the peripheral
        """

        if label in self.entity:
            del self.entity[label]

        if label in self.region:
            del self.region[label]

