            self.instance.ISPR[IRQn >> self.OFFSET] |= 1 << (IRQn & self.MASK)
            self.instance.ICPR[IRQn >> self.OFFSET] |= 1 << (IRQn & self.MASK)
        else:
            self.ql.hw.scb.set_pending(IRQn)

